import json
from abc import ABC, abstractmethod

class JSONHandler(ABC):
    def __init__(self):
        self.factories = {}

    @abstractmethod
    def from_json(self, data: dict) -> object:
        pass

    def to_json(self, obj: object) -> str:
        return json.dumps(obj)

    def add_factory(self, id: str, factory_function):
        self.factories[id] = factory_function

    def create_instance(self, id: str, json_data: str) -> object:
        data = json.loads(json_data)
        return self.factories.get(id)(data)
