import requests
import json
from typing import Dict, List

def modify_kickstart(username: str) -> None:
    response = requests.get(""https://example.com/config_file.json"")
    config_data = json.loads(response.text)

    placeholder_vars = {""username"": username}
    modified_config = {}

    for key, value in config_data.items():
        if isinstance(value, dict):
            modified_config[key] = modify_kickstart(dict_values=value, **placeholder_vars)
        else:
            modified_config[key] = replace_placeholders(value, placeholder_vars)

    with open(""modified_config_file.json"", ""w"") as file:
        json.dump(modified_config, file)

def dict_values(d: Dict) -> Dict:
    for key, value in d.items():
        if isinstance(value, list):
            d[key] = [dict_values(item) for item in value]
        elif isinstance(value, dict):
            d[key] = dict_values(value)
        return d

def replace_placeholders(text: str, placeholders: Dict) -> str:
    for key, value in placeholders.items():
        text = text.replace(f""{{ {key} }}"", value)
    return text

