import json
import os
from concurrent.futures import ThreadPoolExecutor

def load_config(filename):
    with open(filename, 'r') as f:
        return json.load(f)

def configure_parallel_processing(config):
    num_threads = config['thread_count']
    data_filter_threshold = config['data_filter_threshold']
    output_dir = config['output_directory']

    return num_threads, data_filter_threshold, output_dir

def parallel_process(data_list, num_threads, data_filter_threshold, output_dir):
    with ThreadPoolExecutor(max_workers=num_threads) as executor:
        futures = {executor.submit(process_data, data, data_filter_threshold): data for data in data_list}
        results = {}
        for future in futures.values():
            results[future] = future.result()

        os.makedirs(output_dir, exist_ok=True)
        for future, result in results.items():
            with open(os.path.join(output_dir, f""{result}.txt""), 'w') as file:
                file.write(str(result))

if __name__ == ""__main__"":
    config_filename = ""config.json""
    config = load_config(config_filename)
    num_threads, data_filter_threshold, output_dir = configure_parallel_processing(config)
    parallel_process(data_list=[1, 2, 3], num_threads=num_threads, data_filter_threshold=data_filter_threshold, output_dir=output_dir)
