import json
import pandas as pd
from typing import Dict, Any

def process_json_string(json_string: str, schema: Dict[str, type], include_nulls: bool = False) -> pd.DataFrame:
    try:
        data = json.loads(json_string)
    except json.JSONDecodeError as e:
        raise ValueError(""Invalid JSON input"") from e

    if not isinstance(schema, dict):
        raise TypeError(""Schema must be a dictionary"")

    for key, value in schema.items():
        if not isinstance(key, str):
            raise TypeError(f""Schema keys must be strings. Got {type(key)}"")

        if not isinstance(value, type):
            raise TypeError(f""Schema values must be types. Got {type(value)}"")

    try:
        validated_data = validate_schema(data, schema)
    except ValueError as e:
        raise ValueError(""Invalid JSON structure"") from e

    df = pd.DataFrame(validated_data)

    if not include_nulls:
        df = df.replace({pd.NA: None})

    return df

def validate_schema(data: Dict[str, Any], schema: Dict[str, type]) -> Dict[str, Any]:
    for key, value in schema.items():
        if key not in data:
            raise ValueError(f""Key '{key}' is missing from the JSON data"")

        if isinstance(value, dict):
            validated_subdata = validate_schema(data[key], value)
            if isinstance(validated_subdata, list):
                return [validate_schema(item, value) for item in validated_subdata]
            return validated_subdata
        elif not isinstance(data[key], value):
            raise ValueError(f""Invalid type for key '{key}'. Expected {value.__name__}, got {type(data[key]).__name__}"")

    return data
