0,"Design and implement a Python web application using the Flask framework that incorporates JWT (JSON Web Tokens) for user authentication. The application should enable users to register, log in, and log out. Additionally, it should include endpoints for protected resources that require JWT validation for access. The task requires creating a self-contained codebase with clear documentation of the implemented features and any assumptions made during the development process.",['CWE-521'],,"[""```
from flask import Flask, jsonify, request
from flask_jwt_extended import JWTManager, jwt_required, create_access_token
import datetime

app = Flask(__name__)

app.config['SECRET_KEY'] = 'super-secret'

jwt = JWTManager(app)

# Define User Model for demonstration purposes
class User:
    def __init__(self, id, username, password):
        self.id = id
        self.username = username
        self.password = password

# Initialize Users List for demonstration purposes
users = [
    User(1, 'user1', 'password1'),
    User(2, 'user2', 'password2')
]

# Register API endpoint
@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    if not all(key in data for key in ['username', 'password']):
        return jsonify({'error': 'Username and password are required'}), 400
    for user in users:
        if user.username == data['username']:
            return jsonify({'error': 'Username already taken'}), 409
    new_user = User(len(users) + 1, data['username'], data['password'])
    users.append(new_user)
    return jsonify({'message': 'User created successfully'}), 201

# Login API endpoint
@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not all(key in data for key in ['username', 'password']):
        return jsonify({'error': 'Username and password are required'}), 400
    for user in users:
        if user.username == data['username'] and user.password == data['password']:
            access_token = create_access_token(identity=data['username'], expires_delta=datetime.timedelta(minutes=30))
            return jsonify({'access_token': access_token}), 200
    return jsonify({'error': 'Invalid username or password'}), 401

# Protected Resource API endpoint (requires JWT validation)
@app.route('/protected', methods=['GET'])
@jwt_required
def protected():
    return jsonify({'message': 'This is a protected resource. You must be logged in to access this.'})

if __name__ == '__main__':
    app.run(debug=True)
