def parse_binary_and_create_dict(input_file, output_file, rules):
    if not input_file or not output_file:
        print(""Error: Input file and Output file cannot be empty."")
        return None

    try:
        with open(input_file, 'rb') as f:
            data = list(f.read())
    except Exception as e:
        print(f""Error reading the binary file: {str(e)}"")
        return None

    key_values = []
    for i in range(0, len(data), 2):
        key_values.append((chr(data[i]), chr(data[i+1])))

    output_dict = {}
    for key, value in key_values:
        if not isinstance(key, str) or not isinstance(value, (int, float)):
            print(f""Error: Invalid format. Key '{key}' contains non-string characters."")
            return None

        if key.upper() in output_dict:
            output_dict[key.upper()] += value
        else:
            output_dict[key.upper()] = value

    try:
        with open(output_file, 'w') as f:
            json.dump(output_dict, f)
    except Exception as e:
        print(f""Error writing to the output file: {str(e)}"")
        return None
