import csv
from collections import OrderedDict

class CSVData:
    def __init__(self, filename):
        self.filename = filename
        self.data = None

    def load_data(self):
        with open(self.filename, 'r') as file:
            reader = csv.reader(file)
            data = [row for row in reader]
            self.data = OrderedDict()

            for row in data:
                key_value_pair = {}
                for i, cell in enumerate(row):
                    if i % 2 == 0:
                        key_value_pair[cell] = None
                    else:
                        key_value_pair[list(key_value_pair.keys())[0]] = cell
                self.data.setdefault(tuple(sorted(key_value_pair)), {}).update(key_value_pair)

    def display_total_rows(self):
        print(f""Total rows: {len(self.data)}"")

    def get_key_value_pairs(self, keys):
        return [list(self.data.values())[i] for i in keys]

    def memory_cleanup(self):
        self.data = None
        del self

csv_data = CSVData('data.csv')
csv_data.load_data()
csv_data.display_total_rows()

keys_to_display = [0, 1]
print(""Selected key-value pairs:"")
for pair in csv_data.get_key_value_pairs(keys_to_display):
    print(pair)

csv_data.memory_cleanup()
