def caesar_cipher_encrypt(input_string: str, shift_value: int) -> str:
    if not isinstance(input_string, str):
        raise ValueError(""Input must be a string"")
    if not isinstance(shift_value, int):
        raise ValueError(""Shift value must be an integer"")

    if len(input_string) == 0:
        return input_string

    if not 1 <= shift_value <= 25:
        raise ValueError(""Shift value must be between 1 and 25"")

    encrypted_string = """"
    for char in input_string:
