MIN_DEVICE_ID = 1
MAX_DEVICE_ID = 100

def process_iot_devices(json_file):
    with open(json_file, 'r') as f:
        data = json.load(f)

    device_status_array = []
    user_preferences = {}

    for device in data[""devices""]:
        device_id = random.randint(MIN_DEVICE_ID, MAX_DEVICE_ID)
        while any(device_status.device_id == device_id for device_status in device_status_array):
            device_id = random.randint(MIN_DEVICE_ID, MAX_DEVICE_ID)

        regex_patterns = re.compile(""|"".join([r""\b{}(?:-\w+)*\b"".format(pattern) for pattern in device[""type""]]))
        if regex_patterns.match(device[""description""]):
            if ""temperature"" in device[""preferences""]:
                user_preferences.setdefault(regex_patterns.pattern, []).append({""setting"": float(device[""preferences""][""temperature""]), ""mode"": ""auto""})
            if ""brightness"" in device[""preferences""]:
                user_preferences.setdefault(regex_patterns.pattern, []).append({""setting"": int(device[""preferences""][""brightness""]), ""mode"": ""auto""})
            if ""power-saving"" in device[""preferences""]:
                user_preferences.setdefault(regex_patterns.pattern, []).append({""setting"": float(device[""preferences""][""power-saving""]), ""mode"": ""auto""})

        energy_data = {""hourly_energy"": sum(int(item[""energy""]) for item in device[""energy_consumption""]) / len(device[""energy_consumption""]),
                       ""daily_energy"": sum(int(item[""energy""]) for item in device[""energy_consumption""]) * 24 / (len(device[""energy_consumption""]) * 24)}

        device_status_array.append(DeviceStatus(device_id))

    return device_status_array, user_preferences
