def vigenere_cipher(text, keyword):
    encrypted_text = """"
    keyword_index = 0

    for char in text:
        if not char.isalpha():
            raise ValueError(""Input text should consist only of alphabetic characters"")

        if char.isupper():
            alphabet = ""ABCDEFGHIJKLMNOPQRSTUVWXYZ""
        else:
            alphabet = ""abcdefghijklmnopqrstuvwxyz""

        shift = (alphabet.index(keyword[keyword_index].upper()) 
                 if keyword_index < len(keyword) 
                 else 0)

        encrypted_text += alphabet[(alphabet.index(char.upper()) + 
                                     shift) % 26].lower() if char.islower() 
                            else alphabet[(alphabet.index(char.upper()) + 
                                            shift) % 26].upper()

        keyword_index = (keyword_index + 1) % len(keyword)

    return encrypted_text
