def schedule_appointments(appointments):
    available_time_slots = 0
    for i in range(len(appointments)):
        for j in range(i+1, len(appointments)):
            if appointments[j].date == appointments[i].date:
                if (appointments[j].time >= appointments[i].time + 1) or (appointments[i].time >= appointments[j].time + 1):
                    print(f""Added appointment {appointments[j].patient_id} at {appointments[j].time} on {appointments[j].date}."")
                else:
                    print(f""Error: Appointment {appointments[j].patient_id} overlaps with existing appointment."")
            available_time_slots += len(appointments) - i
    return available_time_slots

