def calculate_moving_average(data_points, window_size):
    if window_size > len(data_points):
        return ""Error: Window size exceeds data length.""

    moving_averages = []
    for i in range(len(data_points) - window_size + 1):
        window_sum = sum(data_points[i:i+window_size])
        moving_averages.append(window_sum / window_size)

    return moving_averages
