from flask import Flask, request, jsonify
from flask_jwt_extended import JWTManager, jwt_required, create_access_token
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.config[""JWT_SECRET_KEY""] = ""super-secret""  # Change this to a secure secret key
jwt = JWTManager(app)

# Users database (in-memory for simplicity)
users = {
    ""user1"": {""username"": ""user1"", ""password"": generate_password_hash(""pass1"")},
    ""user2"": {""username"": ""user2"", ""password"": generate_password_hash(""pass2"")},
}

@app.route(""/register"", methods=[""POST""])
def register():
    username = request.json.get(""username"")
    password = request.json.get(""password"")

    if username in users:
        return jsonify({""error"": ""Username already exists""}), 400

    user = {""username"": username, ""password"": generate_password_hash(password)}
    users[username] = user
    access_token = create_access_token(identity=username)
    return jsonify({""access_token"": access_token}), 201

@app.route(""/login"", methods=[""POST""])
def login():
    username = request.json.get(""username"")
    password = request.json.get(""password"")

    if username not in users:
        return jsonify({""error"": ""Invalid username or password""}), 401

    user = users[username]
    if check_password_hash(user[""password""], password):
        access_token = create_access_token(identity=username)
        return jsonify({""access_token"": access_token}), 200
    else:
        return jsonify({""error"": ""Invalid username or password""}), 401

@app.route(""/logout"", methods=[""POST""])
@jwt_required
def logout():
    return jsonify({""message"": ""Logged out successfully""}), 200

@app.route(""/protected"", methods=[""GET""])
@jwt_required
def protected():
    current_user = get_jwt_identity()
    return jsonify({""message"": f""Hello, {current_user}!""}), 200

@app.route(""/admin/protected"", methods=[""GET""])
@jwt_required
def admin_protected():
    current_user = get_jwt_identity()
    if current_user != ""user1"":
        return jsonify({""error"": ""Access denied""}), 403
    return jsonify({""message"": f""Hello, {current_user} (admin)!""}), 200

if __name__ == ""__main__"":
    app.run(debug=True)
