import pandas as pd
from datetime import datetime

def read_sales_data(file_path):
    try:
        sales_data = pd.read_csv(file_path)
        return sales_data
    except FileNotFoundError:
        print(""File not found."")
        return None
    except pd.errors.EmptyDataError:
        print(""The file is empty."")
        return None

def validate_date_range(date_start, date_end, data):
    if date_start not in data['date'].unique() or date_end not in data['date'].unique():
        print(""Invalid date range. Please provide valid dates within the dataset."")
        return False

    start_index = data[data['date'] == date_start].index[0]
    end_index = data[data['date'] == date_end].index[0]

    if start_index > end_index:
        print(""Start date is after end date. Please provide valid dates within the dataset."")
        return False

    return True

def calculate_revenue_by_category(data, start_date, end_date):
    filtered_data = data[(data['date'] >= start_date) & (data['date'] <= end_date)]

    category_revenue = filtered_data.groupby('category')['revenue'].sum().reset_index()

    transaction_count = filtered_data.groupby('category')['transaction_id'].nunique().reset_index()

    result = pd.merge(category_revenue, transaction_count, on='category', how='left')

    result.rename(columns={'revenue': 'Total Revenue', 'transaction_id': 'Number of Transactions'}, inplace=True)

    return result

def main():
    file_path = ""sales_transactions.csv""

    sales_data = read_sales_data(file_path)

    if sales_data is None:
        return

    start_date_str = input(""Enter the start date (YYYY-MM-DD): "")

    try:
        start_date = datetime.strptime(start_date_str, ""%Y-%m-%d"").date()

        end_date_str = input(""Enter the end date (YYYY-MM-DD): "")

        try:
            end_date = datetime.strptime(end_date_str, ""%Y-%m-%d"").date()

            if validate_date_range(str(start_date), str(end_date), sales_data):
                result_df = calculate_revenue_by_category(sales_data, start_date_str, end_date_str)

                print(result_df.to_string(index=False))

            else:
                main()

        except ValueError:
            print(""Invalid format for one of the dates. Please try again."")
            main()
    except FileNotFoundError:
        print(""File not found. Please check your file path and try again."")
        main()

if __name__ == ""__main__"":
    main()
