**Python Code**
```python
import math

def prime_factors(n):
    factors = []
    i = 2
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return sorted(set(factors))

def main():
    num = int(input(""Enter a number: ""))
    print(prime_factors(num))

if __name__ == ""__main__"":
    main()
