import requests
from typing import List

def get_stock_prices(stock_symbols: List[str]) -> dict:
    api_url = ""https://api.example.com/stock-prices""
    response = requests.get(api_url, params={""symbols"": "","".join(stock_symbols)})

    if response.status_code == 200:
        data = response.json()
        stock_prices = {symbol: price[""price""] for symbol, price in zip(stock_symbols, data)}
