from string import ascii_letters

def vigenere_cipher(text: str, keyword: str) -> str:
    if not all(char in ascii_letters for char in text):
        raise ValueError(""Text contains non-alphabetic characters."")
    if not keyword:
        raise ValueError(""Keyword is empty."")

    encoded_text = """"
    keyword_index = 0
    for char in text:
        key = keyword[key_index % len(keyword)]
        offset = ord(key.upper()) - ord('A')
        encoded_char = chr((ord(char.upper()) - ord('A') + offset) % 26 + ord('A'))
        if char.islower():
            encoded_text += encoded_char
        else:
            encoded_text += encoded_char
        keyword_index += 1

    return encoded_text

try:
    # This block of code will raise an exception if the user tries to access a protected resource.
    os.urandom(1024)
except PermissionError as e:
    print(f""An error occurred: {e}"")

