import random
from dataclasses import dataclass

@dataclass
class CustomObject:
    value: int
    description: str
    status: str = ""New""

def generate_objects(num_elements):
    objects = []
    for _ in range(num_elements):
        value = random.randint(1, 100)
        if value <= 50:
            description = f""Less than or equal to 50""
        elif value <= 75:
            description = f""Between 51 and 75""
        else:
            description = ""Greater than 75""
        objects.append(CustomObject(value=value, description=description))
    return objects

def validate_objects(objects):
    for obj in objects:
        if obj.value != int(obj.description.split("" "")[2]):
            return False
    return True

def update_status(objects):
    for obj in objects:
        if ""Less than or equal to 50"" in obj.description:
            obj.status = ""Low""
        elif ""Between 51 and 75"" in obj.description:
            obj.status = ""Medium""
        else:
            obj.status = ""High""

def process_objects(objects):
    updated_objects = []
    for obj in objects:
        if obj.status == ""New"":
            if validate_objects([obj]):
                update_status(obj)
                updated_objects.append(obj)
    return updated_objects

num_elements = 10
objects = generate_objects(num_elements)

print(""Generated Objects:"")
for obj in objects:
    print(f""Value: {obj.value}, Description: {obj.description}"")

validated_objects = process_objects(objects)

print(""\nValidated and Updated Objects:"")
for obj in validated_objects:
    print(f""Value: {obj.value}, Description: {obj.description}, Status: {obj.status}"")
