import pandas as pd
from datetime import datetime

def read_sales_data(file_path):
    try:
        data = pd.read_csv(file_path)
        if len(data) == 0:
            print(""Error: The dataset is empty."")
            return None
        return data
    except FileNotFoundError:
        print(""Error: File not found. Please check the file path."")
        return None

def validate_date_range(start_date, end_date, sales_data):
    try:
        start_datetime = datetime.strptime(start_date, ""%Y-%m-%d"")
        end_datetime = datetime.strptime(end_date, ""%Y-%m-%d"")
    except ValueError:
        print(""Error: Invalid date format. Please enter in YYYY-MM-DD format."")
        return False

    if start_datetime > end_datetime:
        print(""Error: Start date should be before or equal to the end date."")
        return False

    for index, row in sales_data.iterrows():
        sale_date = datetime.strptime(row['sale_date'], ""%Y-%m-%d"")
        if (start_datetime > sale_date) | (end_datetime < sale_date):
            print(""Error: Dates are outside of the dataset range."")
            return False

    return True

def calculate_revenue_by_category(sales_data, start_date, end_date):
    filtered_data = sales_data[(sales_data['sale_date'] >= start_date) & (sales_data['sale_date'] <= end_date)]
    category_sum = filtered_data.groupby('category')['revenue'].sum().reset_index()
    category_count = filtered_data.groupby('category')['revenue'].count().reset_index()
    result = pd.concat([category_sum, category_count], axis=1)
    result.columns = ['category', 'total_revenue', 'num_transactions']
    return result

def main():
    file_path = input(""Enter the CSV file path: "")
    sales_data = read_sales_data(file_path)
    if sales_data is None:
        return

    while True:
        start_date = input(""Enter the start date (YYYY-MM-DD): "")
        end_date = input(""Enter the end date (YYYY-MM-DD): "")

        if validate_date_range(start_date, end_date, sales_data):
            result = calculate_revenue_by_category(sales_data, start_date, end_date)
            print(result)
            break

if __name__ == ""__main__"":
    main()
