import base64
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
from Crypto.Random import get_random_bytes


class AESEncryptor:
    def EncryptMessage(self, input_string: str, key: bytes, iv: bytes) -> bytes:
        cipher = AES.new(key, AES.MODE_CBC, iv)
        encrypted_data = cipher.encrypt(input_string.encode())
        return base64.b64encode(encrypted_data)

    def DecryptMessage(self, encrypted_message: bytes, key: bytes, iv: bytes) -> str:
        decrypted_data = base64.b64decode(encrypted_message)
        try:
            cipher = AES.new(key, AES.MODE_CBC, iv)
            decrypted_string = unpad(cipher.decrypt(decrypted_data), AES.block_size).decode()
            return decrypted_string
        except Exception as e:
            raise EncryptionFailedException(""Encryption failed"") from e


class EncryptionFailedException(Exception):
