import json
from typing import Dict, List

def generate_config(num_services: int, service_params: List[Dict], qos_levels: List[str]) -> str:
    config = {""services"": []}

    if not isinstance(num_services, int) or num_services <= 0:
        raise ValueError(""Number of services must be a positive integer"")

    for i in range(num_services):
        service = {""name"": f""Service {i+1}"", ""qos_level"": qos_levels[i % len(qos_levels)], ""resources"": {}}

        if service_params[i].get(""cpu""):
            service[""resources""][""cpu""] = service_params[i][""cpu""]
        else:
            raise ValueError(""CPU resource requirement missing for Service {}"".format(i+1))

        if service_params[i].get(""memory""):
            service[""resources""][""memory""] = service_params[i][""memory""]
        else:
            raise ValueError(""Memory resource requirement missing for Service {}"".format(i+1))

        if service_params[i].get(""bandwidth""):
            service[""resources""][""bandwidth""] = service_params[i][""bandwidth""]
        else:
            raise ValueError(""Bandwidth resource requirement missing for Service {}"".format(i+1))

        config[""services""].append(service)

    with open(""config.json"", ""w"") as f:
        json.dump(config, f, indent=4)

    return ""Configuration file generated successfully""
