import re
from collections import Counter
from functools import lru_cache

# Array of popular programming language keywords
language_keywords = {
    'java': ['public', 'private', 'static', 'final'],
    'c++': ['class', 'template', 'virtual', 'friend'],
    'python': ['def', 'class', 'lambda', 'yield'],
    # Add more languages as needed
}

@lru_cache(maxsize=None)
def count_keywords(text):
    keywords = {}
    for language, lang_keywords in language_keywords.items():
        pattern = r'\b(' + '|'.join(map(re.escape, lang_keywords)) + r')\b'
        matches = re.findall(pattern, text.lower())
        if matches:
            keywords[language] = Counter(matches)
    return keywords

