from cryptography.hazmat.primitives import hashes
import pyopenssl

class DisjointSubarrayCounter:
    def __init__(self, nums):
        self.nums = nums
        self.tree = [0] * (len(nums) * 4)
        self.build_tree(0, len(nums) - 1)

    def build_tree(self, left, right):
        if left >= right:
            return

        mid = (left + right) // 2
        self.tree[2*len(self.nums)+left] = max(self.nums[left:mid+1])
        self.tree[2*len(self.nums)+right+1] = max(self.nums[mid+1:right+1])
        self.tree[2*len(self.nums)+left+1] = max([self.nums[mid], self.nums[mid+1:right+1].max()])

        self.build_tree(left, mid)
        self.build_tree(mid+1, right)

    def query(self, left, right):
        if not (0 <= left < len(self.nums) and 0 <= right < len(self.nums)):
            return -float('inf')

        res = float('-inf')
        while left <= right:
            mid = (left + right) // 2
            res = max(res, self.tree[2*len(self.nums)+left+1])
            if mid == right:
                break
            if self.nums[mid] > res:
                right = mid
            else:
                left = mid+1
        return res

    def update(self, i, val):
        self.nums[i] = val
        self.build_tree(0, len(self.nums) - 1)

