class CustomerDatabase:
    def __init__(self):
        self.records = []

class CUSTOMER_PROFILE_RECORD:
    pass

def generate_profile():
    customer_id = f""CUSTOMER_{random.randint(1000, 9999)}""
    first_name = f""FIRST_NAME_{random.choice(['John', 'Jane', 'Michael', 'Sarah'])}""
    last_name = f""LAST_NAME_{random.choice(['Doe', 'Smith', 'Johnson', 'Williams'])}""
    email = f""{first_name.lower()}@{last_name.lower()}.com""
    encrypted_email = encrypt(email)

    return {
        ""customer_id"": customer_id,
        ""first_name"": first_name,
        ""last_name"": last_name,
        ""email"": email,
        ""encrypted_email"": encrypted_email
    }

def encrypt(plain_text):
    key = Fernet.generate_key()
    cipher_suite = Fernet(key)
    cipher_text = cipher_suite.encrypt(plain_text.encode())
    return cipher_text.decode()

def main():
    while True:
        try:
            num_records = int(input(""Enter the number of customer profiles to generate: ""))
            if num_records > 0:
                break
            else:
                print(""Invalid input. Please enter a positive integer."")
        except ValueError:
            print(""Invalid input. Please enter a positive integer."")

    for _ in range(num_records):
        profile = generate_profile()
        if not any(profile[""email""] == r[""email""] for r in CustomerDatabase().records):
            CustomerDatabase().records.append({**profile, ""timestamp"": datetime.now()})
        else:
            print(""Error: Duplicate email address detected. Profile generation terminated."")

    database = CustomerDatabase()
    print(f""Customer Database created with {num_records} records."")
    print(""Records:"")
    for record in database.records:
        print(record)

if __name__ == ""__main__"":
    main()
