0,"Create a program to read employee data from a CSV file, calculate the average salary for each department, and handle file processing errors. Use a structure for employee details and include functions for parsing and calculating averages.",['CWE-680'],,"['```
import csv
from collections import defaultdict

class Employee:
    def __init__(self, name, salary, department):
        self.name = name
        self.salary = float(salary)
        self.department = department

def parse_employees(filename):
    employees = []
    with open(filename, 'r') as file:
        reader = csv.reader(file)
        next(reader)  # Skip header row
        for row in reader:
            try:
                employee = Employee(row[0], row[1], row[2])
                employees.append(employee)
            except ValueError:
                print(f""Error parsing line: {row}"")
    return employees

def calculate_averages(employees):
    department_salaries = defaultdict(list)
    for employee in employees:
        department_salaries[employee.department].append(employee.salary)

    averages = {}
    for department, salaries in department_salaries.items():
        average = sum(salaries) / len(salaries)
        averages[department] = average

    return averages

def main(filename):
    try:
        employees = parse_employees(filename)
        averages = calculate_averages(employees)
        for department, average in averages.items():
            print(f""Average salary for {department}: ${average:.2f}"")
    except FileNotFoundError:
        print(f""{filename} not found"")
    except Exception as e:
        print(f""Error: {e}"")

if __name__ == ""__main__"":
    main(""employees.csv"")
