from datetime import timedelta

class TrackMergingSystem:
    def __init__(self):
        self.api_cache = {}

    @retry(wait_exponential_max=60)
    def fetch_recommendations(self, genre, user_tracks):
        api_url = f""https://api.recommendation.com/v1/tracks?genre={genre}""
        response = requests.get(api_url)

        if response.status_code == 200:
            return response.json()
        elif response.status_code == 503:
            raise Exception(""API temporarily unavailable. Retrying..."")
        else:
            raise Exception(f""Failed to fetch recommendations: {response.status_code}"")

    @retry(wait_exponential_max=60)
    def fetch_artist_popularity(self, artist_id):
        api_url = f""https://api.artist.com/v1/popularity/{artist_id}""
        response = requests.get(api_url)

        if response.status_code == 200:
            return response.json()
        elif response.status_code == 503:
            raise Exception(""API temporarily unavailable. Retrying..."")
        else:
            raise Exception(f""Failed to fetch artist popularity: {response.status_code}"")

    @retry(wait_exponential_max=60)
    def fetch_song_popularity(self, song_id):
        api_url = f""https://api.song.com/v1/popularity/{song_id}""
        response = requests.get(api_url)

        if response.status_code == 200:
            return response.json()
        elif response.status_code == 503:
            raise Exception(""API temporarily unavailable. Retrying..."")
        else:
            raise Exception(f""Failed to fetch song popularity: {response.status_code}"")

    def merge_tracks(self, user_tracks, genre_filter, max_recommendations):
        if not user_tracks:
            return []

        unique_tracks = set()
        for track in user_tracks:
            unique_tracks.add(track['track_id'])

        recommended_tracks = []
        for i in range(max_recommendations):
            try:
                response = self.fetch_recommendations(genre_filter, user_tracks)
                recommendations = response['tracks']
                break
            except Exception as e:
                if isinstance(e, requests.exceptions.Timeout):
                    raise
                print(f""Error fetching recommendations: {e}"")
                continue

        merged_tracks = list(unique_tracks)
        for track in recommendations[:max_recommendations]:
            if track['track_id'] not in unique_tracks:
                merged_tracks.append(track)

        return merged_tracks

    def filter_played_tracks(self, tracks, time_frame):
        played_tracks = []
        # fetch played tracks from database or API
        for track in tracks:
            if track['played'] > datetime.now() - timedelta(days=time_frame):
                played_tracks.append(track)
        return [track for track in tracks if track not in played_tracks]

    def save_playlist(self, playlist_name, tracks):
