from flask import Flask, render_template, request
import json
import sys

app = Flask(__name__)

def validate_config(config):
    if 'max_post_length' in config:
        if not isinstance(config['max_post_length'], int) or config['max_post_length'] < 1:
            raise ValueError('Invalid max_post_length')

@app.route('/')
def index():
    return render_template('index.html')

if __name__ == '__main__':
    try:
        with open(sys.argv[1], 'r') as f:
            config = json.load(f)
    except IndexError:
        print(""Please provide a configuration file path as an argument."")
        sys.exit(1)
    except FileNotFoundError:
        print(""The provided configuration file was not found."")
        sys.exit(1)
    validate_config(config)

app.config.update(config)

from werkzeug.utils import secure_filename

@app.route('/posts', methods=['POST'])
def create_post():
    if request.method == 'POST':
        file = request.files['post']
        filename = secure_filename(file.filename)
        with open(f'posts/{filename}', 'w') as f:
            f.write(file.stream.read())
        return 'Post created successfully.', 201

if __name__ == '__main__':
    app.run(debug=True, use_reloader=True)
