import random
import socket
import time

class TCPConnectionRecord:
    def __init__(self):
        self.source_ip = """"
        self.dest_ip = """"
        self.source_port = 0
        self.dest_port = 0
        self.status = ""closed""
        self.duration = 0

class ProcessedLine:
    def __init__(self):
        self.record = TCPConnectionRecord()

def isValidIP(ip):
    try:
        socket.inet_aton(ip)
        return True
    except socket.error:
        return False

def isValidPort(port):
    if port < 1 or port > 65535:
        return False
    return True

def generate_tcp_connections(filename):
    with open(filename, 'r') as file:
        lines = file.readlines()

    records = [TCPConnectionRecord() for _ in range(len(lines))]

    for i, line in enumerate(lines):
        record = records[i]
        record.source_ip = f""{random.randint(1, 254)}.{random.randint(1, 254)}.{random.randint(1, 254)}.{random.randint(1, 254)}""
        record.dest_ip = f""{random.randint(1, 254)}.{random.randint(1, 254)}.{random.randint(1, 254)}.{random.randint(1, 254)}""
        record.source_port = random.randint(1, 65535)
        record.dest_port = random.randint(1, 65535)

    for i in range(len(lines)):
        if not isValidIP(records[i].source_ip) or not isValidPort(records[i].source_port) or not isValidIP(records[i].dest_ip) or not isValidPort(records[i].dest_port):
            print(f""Invalid IP/Port at line {i+1}"")

    timestamps = [time.time() + random.uniform(0, 3600) for _ in range(len(lines))]
    connection_durations = [(timestamps[i] - timestamps[i-1]) if i > 0 else 0 for i in range(1, len(lines))]

    for i in range(len(lines)):
        record = records[i]
        if timestamps[i] < timestamps[0]:
            record.status = ""established""
        elif timestamps[i] > timestamps[-1]:
            record.status = ""listening""
        else:
            record.status = ""closed""

    return records

print(generate_tcp_connections(""test.txt""))
