    valid_range = (0, 0x7FFFFFFF)

    for timestamp in timestamps:
        if not (valid_range[0] <= timestamp <= valid_range[1]):
            raise ValueError(f""Timestamp {timestamp} is out of range [{valid_range[0]}-{valid_range[1]}]"")

def enhanced_generate_check_ntp():
