import asyncio
import websockets

class ConnectionManager:
    def __init__(self):
        self.connections = {}

    async def connect(self, host, port, heartbeat_interval=5000, reconnection_attempts=3):
        connection_id = f""{host}:{port}""
        if connection_id in self.connections:
            return self.connections[connection_id]

        try:
            async with websockets.connect(f""ws://{host}:{port}"") as ws:
                self.connections[connection_id] = ws
                await self.heartbeat(ws, heartbeat_interval)
                for _ in range(reconnection_attempts):
                    try:
                        await ws.recv()
                    except ConnectionResetError:
                        await self.reconnect(ws)
                        break
        finally:
            if connection_id in self.connections:
                del self.connections[connection_id]

    async def heartbeat(self, ws, interval=5000):
        while True:
            try:
                await ws.send("""")
                await asyncio.sleep(interval / 1000.0)
            except ConnectionResetError:
                break

    async def reconnect(self, ws):
        for _ in range(3):
            try:
                await ws.connect()
                return
            except websockets.ConnectionClosed:
                await asyncio.sleep(1)

class PerformanceTester:
    async def test_connection_manager(self, connection_manager):
        # Test successful data transmission
        await connection_manager.connect(""localhost"", 8080)
        await connection_manager.send_data(""Test message"")

        # Test disconnection handling
        await connection_manager.disconnect()

        # Test reconnection scenarios
        for _ in range(3):
            await connection_manager.reconnect()

    async def send_data(self, ws, data):
        try:
            await ws.send(data)
        except ConnectionResetError:
            pass

    async def disconnect(self, ws):
        try:
            await ws.close()
        except ConnectionResetError:
            pass

async def main():
    connection_manager = ConnectionManager()
    tester = PerformanceTester()

    # Test with default heartbeat interval and reconnection attempts
    await tester.test_connection_manager(connection_manager)

    # Test with custom heartbeat interval and reconnection attempts
    await connection_manager.connect(""localhost"", 8081, 2000, 2)
    await tester.send_data(connection_manager.connections[""localhost:8081""], ""Test message"")
