import asyncio
import websockets
from typing import Dict, List

class ConnectionManager:
    def __init__(self):
        self.connections: Dict[str, websockets.WebSocket] = {}
        self.heartbeat_intervals: Dict[str, int] = {}
        self.reconnection_attempts: Dict[str, int] = {}
        self.backoff_strategies: Dict[str, str] = {}

    async def establish_connection(self, url: str, interface: str):
        try:
            connection = await websockets.connect(url=url, interface=interface)
            self.connections[url] = connection
            # Set custom heartbeat interval and reconnection attempts if required
            if url in self.heartbeat_intervals:
                await connection.send(f""hb:{self.heartbeat_intervals[url]}"")
            if url in self.reconnection_attempts:
                await connection.send(f""reconnect-attempts:{self.reconnection_attempts[url]}"")
        except ConnectionRefusedError as e:
            print(f""Connection failed: {e}"")

    async def send_message(self, message: str):
        for url, connection in self.connections.items():
            try:
                await connection.send(message)
            except Exception as e:
                print(f""Send error: {e}"")
                # Handle disconnection gracefully
                if ""disconnection"" not in message.lower():
                    await connection.close()

    async def receive_message(self):
        for url, connection in self.connections.items():
            try:
                message = await connection.recv()
                print(f""Received message from {url}: {message}"")
            except Exception as e:
                print(f""Receive error: {e}"")

    def set_heartbeat_interval(self, url: str, interval: int):
        self.heartbeat_intervals[url] = interval

    def set_reconnection_attempts(self, url: str, attempts: int):
        self.reconnection_attempts[url] = attempts

    def set_backoff_strategy(self, url: str, strategy: str):
        self.backoff_strategies[url] = strategy

class QoSManager:
    def __init__(self):
        self.qos_levels: Dict[str, int] = {}

    def set_qos_level(self, level: str, priority: int):
        self.qos_levels[level] = priority

    def prioritize_data(self, data: str, qos_level: str):
        if qos_level in self.qos_levels:
            return f""{data} (Priority {self.qos_levels[qos_level]})""
        else:
            return data

class SecurityManager:
    def __init__(self):
        self.security_policies: Dict[str, List[str]] = {}

    def set_security_policy(self, policy_name: str, access_control_list: List[str]):
        self.security_policies[policy_name] = access_control_list

    def authorize_access(self, policy_name: str, url: str) -> bool:
        if policy_name in self.security_policies:
            return url in self.security_policies[policy_name]
        else:
            return True

async def test_connection_manager():
    cm = ConnectionManager()
    # Establish connections and set custom heartbeat intervals
    await cm.establish_connection(""ws://localhost:8080"", ""eth0"")
    cm.set_heartbeat_interval(""ws://localhost:8080"", 500)
    cm.set_reconnection_attempts(""ws://localhost:8080"", 3)

    # Send messages and receive responses
    await cm.send_message(""Hello, WebSocket!"")
    await cm.receive_message()

    # Test disconnection handling with graceful degradation
    await cm.send_message(""Disconnect me, please!"")
    # ...

async def test_qos_manager():
    qm = QoSManager()
    qm.set_qos_level(""high"", 1)
    qm.set_qos_level(""medium"", 0.5)

    # Prioritize high-priority data packets
    data = ""Hello, WebSocket!""
    prioritized_data = qm.prioritize_data(data, ""high"")
    print(prioritized_data)

async def test_security_manager():
    sm = SecurityManager()
    sm.set_security_policy(""policy1"", [""ws://localhost:8080""])
    sm.set_security_policy(""policy2"", [])

    # Test authorization
    authorized = sm.authorize_access(""policy1"", ""ws://localhost:8080"")
    print(f""Authorized: {authorized}"")

async def main():
    await test_connection_manager()
    await test_qos_manager()
    await test_security_manager()

asyncio.run(main())
