import datetime
import random

class ProjectMilestone:
    def __init__(self, project_id, timestamp, milestone_type):
        self.project_id = project_id
        self.timestamp = timestamp
        self.milestone_type = milestone_type
        self.time_spent = 0

def isValidID(id):
    return len(set(id.split(','))) == 1

def isValidTimestamp(timestamp):
    try:
        dt = datetime.datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
        return True
    except ValueError:
        return False

def parse_file(file_path):
    project_milestones = []
    with open(file_path, 'r') as file:
        for line in file:
            id = str(random.randint(1, 10000))
            timestamp = datetime.datetime.now() + datetime.timedelta(minutes=random.randint(0, 1440))
            milestone_type = random.choice(['Code Commit', 'Feature Completion', 'Bug Fix'])

            if isValidID(id) and isValidTimestamp(str(timestamp)):
                project_milestones.append(ProjectMilestone(id, str(timestamp), milestone_type))
    return project_milestones

def main():
    file_path = input(""Enter the file path: "")

    try:
        project_milestones = parse_file(file_path)

        if len(project_milestones) > 0:
            print(""Project Milestones:"")
            for i, milestone in enumerate(project_milestones):
                print(f""ID: {milestone.project_id}, Timestamp: {milestone.timestamp}, Type: {milestone.milestone_type}"")

            milestones = {}
            total_time_spent = sum(milestone.time_spent for milestone in project_milestones)

            for milestone in project_milestones:
                if milestone.milestone_type not in milestones:
                    milestones[milestone.milestone_type] = 0
                milestones[milestone.milestone_type] += 1

            print(f""Total time spent: {total_time_spent} days"")
            print(""Most frequent milestones achieved:"")
            for milestone, count in sorted(milestones.items(), key=lambda x: x[1], reverse=True):
                print(f""{milestone}: {count}"")
        else:
            print(""No project milestones found."")

    except Exception as e:
        print(f""Error occurred: {str(e)}"")

if __name__ == ""__main__"":
    main()
