@jwt_required
def get_weather_data(username):
    # Fetch real-time weather data from external API (e.g. OpenWeatherMap)
    api_response = requests.get('https://api.openweathermap.org/data/2.5/weather?q=London,uk&units=metric')

    if api_response.status_code == 200:
        return json.loads(api_response.text)

@cache.cached(timeout=60)  # Cache for 1 minute
def get_weather_data(username):
    # Fetch real-time weather data from external API (e.g. OpenWeatherMap)
    api_response = requests.get('https://api.openweathermap.org/data/2.5/weather?q=London,uk&units=metric')

    if api_response.status_code == 200:
        return json.loads(api_response.text)

@jwt_required
@app.route('/weather', methods=['GET'])
def get_weather():
    user_id = get_jwt_identity()
    weather_data = get_weather_data(user_id)
    return jsonify(weather_data), 200

@jwt_required
@app.route('/login', methods=['POST'])
def login():
