class Transaction:
    def __init__(self, timestamp, weight):
        self.timestamp = timestamp
        self.weight = weight

class TransactionProcessor:
    def __init__(self):
        self.window = []
        self.fibonacci_coefficients = [1, 1]

    def add_transaction(self, transaction):
        if len(self.window) >= 5:
            oldest_timestamp = max(t.timestamp for t in self.window)
            if transaction.timestamp > oldest_timestamp:
                self.window.pop(0)

        adjusted_weight = abs(transaction.weight) / (abs(transaction.weight) + 1)
        weighted_sum = sum(t.weight * c for t, c in zip(self.window, self.fibonacci_coefficients))
        weighted_sum += transaction.weight

        self.fibonacci_coefficients.append(sum(self.fibonacci_coefficients[-2:]))
        self.window.insert(0, transaction)

    def get_weighted_sum(self):
        return sum(t.weight * c for t, c in zip(self.window, self.fibonacci_coefficients))
