        node.target_state = random.randint(min_val, max_val)

    return nodes

def calculate_diff(node_states):
    diffs = []
    for node in node_states:
        diff = abs(node.current_state - node.target_state)
        diffs.append(f""Node {node.node_id}: Current State - {node.current_state}, Target State - {node.target_state}, Difference - {diff}"")

    return '\n'.join(diffs)

def save_node_states(node_states, filename):
    with open(filename, 'w') as file:
        for node in node_states:
            file.write(f""Node {node.node_id}: Current State - {node.current_state}, Target State - {node.target_state}\n"")

def main():
    if len(sys.argv) < 4 or len(sys.argv) > 5:
        print(""Usage: python distributed_system.py <num_nodes> [<min_val>] [<max_val>] [output_file]"")
        sys.exit(1)

    try:
        num_nodes = int(sys.argv[1])
        min_val = int(sys.argv[2]) if len(sys.argv) >= 4 else 0
        max_val = int(sys.argv[3]) if len(sys.argv) >= 4 else 100

        node_states = generate_node_states(num_nodes, min_val, max_val)

        if len(sys.argv) == 5:
            save_node_states(node_states, sys.argv[4])
        else:
            print(calculate_diff(node_states))

    except ValueError as e:
        print(f""Error: {e}"")
        sys.exit(1)

if __name__ == ""__main__"":
    main()
