class CodeFormatter:
    def __init__(self):
        self.format_styles = {
            'java': r'\b(?P<indent>\s*)\S+(?=[\{\(])',
            'python': r'^(?P<indent> *)def|(?P<indent> *)class|'
                      r'^(?P<indent> *)elif|^(?P<indent> *)else:',
