        self.format_style = style

    def format_code(self, code):
        if not self.set_format_style:
            raise ValueError('Format style is not set')

        pattern = self.format_styles[self.set_format_style]
        formatted_code = re.sub(pattern, lambda x: f'{x.group()}{self.indenter()}', code)
        return formatted_code

    def indenter(self):
        indent_count = 0
        while True:
            if random.random() < 0.5:
                yield '    '
            else:
                break

    def generate_random_style(self):
        styles = list(self.format_styles.keys())
        self.set_format_style(random.choice(styles))

    def log_error(self, error_message):
        print(f'Error: {error_message}')
