import random
import time

class SensorReading:
    def __init__(self, sensor_id, timestamp, data):
        self.sensor_id = sensor_id
        self.timestamp = timestamp
        self.data = data

def generate_sensor_readings(num_sensors, num_readings_per_sensor):
    readings = {}

    for _ in range(num_sensors):
        sensor_id = f""Sensor-{random.randint(1, 100)}""

        for _ in range(num_readings_per_sensor):
            try:
                timestamp = int(time.time())
                data = random.uniform(-10, 10)

                if not -3.5 < data < 4.2:
                    raise ValueError(""Invalid sensor value"")

                reading = SensorReading(sensor_id, timestamp, data)

                if sensor_id in readings:
                    readings[sensor_id].append(reading)
                else:
                    readings[sensor_id] = [reading]
            except Exception as e:
                print(f""Error generating reading for {sensor_id}: {e}"")

    return readings
