import uuid
from datetime import datetime
import random

def generateLogEntries(numEntries):
    log_entries = []
    for _ in range(numEntries):
        unique_id = str(uuid.uuid4().int)
        timestamp = datetime.now().strftime(""%Y-%m-%d %H:%M:%S"")
        message = ''.join(random.choices('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ !.,', k=random.randint(1, 100)))
        log_entry = {'unique_id': unique_id, 'timestamp': timestamp, 'message': message}
        log_entries.append(log_entry)
    return log_entries

def validateLogEntry(log_entry):
    try:
        datetime.strptime(log_entry['timestamp'], ""%Y-%m-%d %H:%M:%S"")
