def rotated_substring_cipher(text: str, rotation_key: str):
    if not text.isalpha():
        raise ValueError(""Text contains non-alphabetic characters"")
    if not rotation_key:
        raise ValueError(""Rotation key is empty"")

    encrypted_text = """"
    for char in text.upper():
        if char.isalpha():
            shift = 0
            if char.isupper():
                shift = ord('A')
            else:
                shift = ord('a')

            position = (ord(char) - shift + rotation_key.index(next((c for c in rotation_key if c == char.lower())))) % 26
            encrypted_text += chr(position + shift)
        else:
            encrypted_text += char

    return encrypted_text']",0,[0],[],True,0,0,0,

